/* Local-match map list: stock maps plus maps downloaded from online servers.
 * Excluded: maps that need a mod (in a mod folder, LMS-only arenas, no objective script, or a script
 * this game rejects). Marked: maps with Omni-bot navigation (<omnibot_path>/et/nav/<map>.way).
 * Output et-rust/maplist.txt for the UI: "map<TAB>bots<TAB>long name" lines, bot maps first. */
#include "../engine/src/client/client.h"
#include "../engine/src/qcommon/unzip.h"
#include "../engine/src/win32/win_local.h"
#include "et_script_names.h" /* Generated by CMake from engine/src/game/g_script.c. */

#define MAX_LISTED 256
typedef struct { char name[64], longname[96]; qboolean bots; } mapEntry_t;
static mapEntry_t maps[MAX_LISTED];
static int mapCount;

/* Case-insensitive substring test. */
static qboolean Has(const char *text, const char *needle) {
    int n = strlen(needle);
    for (; *text; ++text) if (!Q_stricmpn(text, needle, n)) return qtrue;
    return qfalse;
}
static qboolean Known(const char *const *list, const char *token) {
    for (; *list; ++list) if (!Q_stricmp(*list, token)) return qtrue;
    return qfalse;
}

/* One G_Script_ScriptParse pass for an entity named `name`, same tokenizer and checks.
 * Returns NULL if the game would accept it, else the reason the map would fail to load. */
static const char *ScriptPass(const char *script, const char *name) {
    static char reason[128];
    char *p = (char *)script, *token;
    qboolean wantName = qtrue, inScript = qfalse;
    int bracketLevel = 0;
    COM_BeginParseSession("MapListScript");
    for (;;) {
        token = COM_Parse(&p);
        if (!token[0]) return wantName ? NULL : "unexpected end of script";
        if (token[0] == '}') {
            if (inScript) return NULL;
            if (wantName) return "unexpected '}'";
            wantName = qtrue;
        } else if (token[0] == '{') {
            if (wantName) return "'{' without a name";
        } else if (wantName) {
            if (!Q_stricmp(token, "bot")) { SkipRestOfLine(&p); SkipBracedSection(&p); continue; }
            if (!Q_stricmp(token, "entity")) continue;
            inScript = !Q_stricmp(token, name);
            wantName = qfalse;
        } else if (inScript) {
            if (!Known(etScriptEvents, token)) { Com_sprintf(reason, sizeof(reason), "unknown event %s", token); return reason; }
            while ((token = COM_Parse(&p))[0] != '{') if (!token[0]) return "unexpected end of script";
            while ((token = COM_Parse(&p))[0] != '}') {
                if (!token[0]) return "unexpected end of script";
                if (!Known(etScriptActions, token)) { Com_sprintf(reason, sizeof(reason), "unknown action %s", token); return reason; }
                if (!Q_stricmp(token, "set")) {
                    COM_Parse(&p); /* '{' (the game only warns otherwise) */
                    while ((token = COM_Parse(&p))[0] && token[0] != '}') {}
                } else while (COM_ParseExt(&p, qfalse)[0]) {}
            }
        } else {
            while ((token = COM_Parse(&p))[0]) {
                if (token[0] == '{') ++bracketLevel;
                else if (token[0] == '}' && !--bracketLevel) break;
            }
            if (!token[0]) return "unexpected end of script";
        }
    }
}

/* Reads the entity lump (lump 0) of an IBSP v47 map; pk3 files only read forward. */
static char *Entities(const char *bsp) {
    fileHandle_t f;
    int header[2 + 17 * 2], length = FS_FOpenFileRead(bsp, &f, qtrue), at = sizeof(header), want;
    static char skip[65536];
    char *text = NULL;
    if (length <= 0 || !f) return NULL;
    if (FS_Read(header, sizeof(header), f) == sizeof(header) && LittleLong(header[0]) == (('P' << 24) | ('S' << 16) | ('B' << 8) | 'I') &&
        LittleLong(header[1]) == 47) {
        int offset = LittleLong(header[2]), size = LittleLong(header[3]);
        if (offset >= at && size > 0 && size < (8 << 20) && offset + size <= length) {
            while (at < offset && (want = offset - at < (int)sizeof(skip) ? offset - at : (int)sizeof(skip)) && FS_Read(skip, want, f) == want) at += want;
            text = Z_Malloc(size + 1);
            if (at != offset || FS_Read(text, size, f) != size) { Z_Free(text); text = NULL; }
            else text[size] = 0;
        }
    }
    FS_FCloseFile(f);
    return text;
}

/* The map's script against every scripted entity it really contains. */
static const char *CheckScript(const char *map) {
    static char reason[160];
    char *script, *entities, *p, *token, key[64], names[512][64];
    int count = 0, i, j;
    const char *error = NULL;
    if (FS_ReadFile(va("maps/%s.script", map), (void **)&script) <= 0) return "no objective script";
    if (!(entities = Entities(va("maps/%s.bsp", map)))) { FS_FreeFile(script); return "unreadable map"; }
    p = entities;
    COM_BeginParseSession("MapListEntities");
    while ((token = COM_Parse(&p))[0]) {
        if (token[0] == '{' || token[0] == '}') continue;
        Q_strncpyz(key, token, sizeof(key));
        token = COM_Parse(&p);
        if (Q_stricmp(key, "scriptname") || !token[0]) continue;
        for (j = 0; j < count && Q_stricmp(names[j], token); ++j) {}
        if (j == count && count < 512) Q_strncpyz(names[count++], token, sizeof(names[0]));
    }
    for (i = 0; i < count && !error; ++i) error = ScriptPass(script, names[i]);
    if (error) Com_sprintf(reason, sizeof(reason), "%s", error);
    Z_Free(entities); FS_FreeFile(script);
    return error ? reason : NULL;
}

/* Arena files: long name and game types per map. */
static void ArenaInfo(const char *map, char *longname, int size, qboolean *arena, qboolean *objective) {
    static char files[32768];
    int count = FS_GetFileList("scripts", ".arena", files, sizeof(files)), i;
    char *file = files;
    *arena = *objective = qfalse;
    Q_strncpyz(longname, map, size);
    for (i = 0; i < count; ++i, file += strlen(file) + 1) {
        char *text, *p, *token, key[32], name[64] = "", title[96] = "", type[128] = "";
        if (FS_ReadFile(va("scripts/%s", file), (void **)&text) <= 0) continue;
        p = text;
        COM_BeginParseSession("MapListArena");
        while ((token = COM_Parse(&p))[0]) {
            if (token[0] == '{') { name[0] = title[0] = type[0] = 0; continue; }
            if (token[0] == '}') {
                if (!Q_stricmp(name, map)) {
                    *arena = qtrue;
                    if (title[0]) Q_strncpyz(longname, title, size);
                    if (Has(type, "wolfmp")) *objective = qtrue;
                }
                continue;
            }
            Q_strncpyz(key, token, sizeof(key));
            token = COM_Parse(&p);
            if (!Q_stricmp(key, "map")) Q_strncpyz(name, token, sizeof(name));
            else if (!Q_stricmp(key, "longname")) Q_strncpyz(title, token, sizeof(title));
            else if (!Q_stricmp(key, "type")) Q_strncpyz(type, token, sizeof(type));
        }
        FS_FreeFile(text);
    }
}

static qboolean HasNavigation(const char *map) {
    char base[MAX_OSPATH];
    Q_strncpyz(base, Cvar_VariableString("omnibot_path"), sizeof(base));
    if (!base[0]) Q_strncpyz(base, FS_BuildOSPath(Cvar_VariableString("fs_basepath"), "omnibot", ""), sizeof(base));
    return GetFileAttributesA(va("%s/et/nav/%s.way", base, map)) != INVALID_FILE_ATTRIBUTES;
}

static int Compare(const void *a, const void *b) {
    const mapEntry_t *x = a, *y = b;
    char left[96], right[96];
    if (x->bots != y->bots) return x->bots ? -1 : 1;
    Q_strncpyz(left, x->longname, sizeof(left)); Q_strncpyz(right, y->longname, sizeof(right));
    return Q_stricmp(Q_CleanStr(left), Q_CleanStr(right));
}

/* Script results are cached by map + file sizes: reading a downloaded BSP's entities is slow. */
#define CACHE_FILE "maplist.cache"
static const char *Cached(char *cache, const char *key) {
    char *line = cache ? strstr(cache, va("\n%s\t", key)) : NULL;
    static char value[160];
    int n = 0;
    if (!line) return NULL;
    line += strlen(key) + 2;
    while (line[n] && line[n] != '\n' && n < (int)sizeof(value) - 1) { value[n] = line[n]; ++n; }
    value[n] = 0;
    return value;
}

void CL_ScanMaps(void) {
    char **files, *cache = NULL, *raw;
    int count, i, excluded = 0, bots = 0, length;
    fileHandle_t out, newCache;
    if (CL_OnlinePane() || Q_stricmp(Cvar_VariableString("fs_game"), "et-rust")) return; /* Local menu only. */
    if ((length = FS_ReadFile(CACHE_FILE, (void **)&raw)) > 0) {
        cache = Z_Malloc(length + 2); cache[0] = '\n'; memcpy(cache + 1, raw, length); cache[length + 1] = 0;
        FS_FreeFile(raw);
    }
    newCache = FS_FOpenFileWrite(CACHE_FILE);
    mapCount = 0;
    files = FS_ListFiles("maps", ".bsp", &count);
    for (i = 0; i < count && mapCount < MAX_LISTED; ++i) {
        char name[64], key[128];
        const char *reason = NULL, *cached;
        qboolean arena, objective;
        fileHandle_t f;
        int bspLength, scriptLength;
        COM_StripExtension(files[i], name);
        if (strchr(name, '/') || strchr(name, '\\') || strlen(name) >= sizeof(maps[0].name)) continue;
        ArenaInfo(name, maps[mapCount].longname, sizeof(maps[0].longname), &arena, &objective);
        bspLength = FS_FOpenFileRead(va("maps/%s.bsp", name), &f, qtrue); if (f) FS_FCloseFile(f);
        scriptLength = FS_FOpenFileRead(va("maps/%s.script", name), &f, qtrue); if (f) FS_FCloseFile(f);
        Com_sprintf(key, sizeof(key), "%s %d %d", name, bspLength, scriptLength);
        if (arena && !objective) reason = "no objective game type";
        else if ((cached = Cached(cache, key))) reason = !strcmp(cached, "ok") ? NULL : cached;
        else reason = CheckScript(name);
        if (newCache && !(arena && !objective)) {
            const char *line = va("%s\t%s\n", key, reason ? reason : "ok");
            FS_Write(line, strlen(line), newCache);
        }
        if (reason) { ++excluded; Com_DPrintf("MAPLIST excluded map=%s reason=%s\n", name, reason); continue; }
        Q_strncpyz(maps[mapCount].name, name, sizeof(maps[0].name));
        maps[mapCount].bots = HasNavigation(name);
        bots += maps[mapCount].bots;
        ++mapCount;
    }
    FS_FreeFileList(files);
    if (newCache) FS_FCloseFile(newCache);
    if (cache) Z_Free(cache);
    qsort(maps, mapCount, sizeof(maps[0]), Compare);
    if ((out = FS_FOpenFileWrite("maplist.txt"))) {
        for (i = 0; i < mapCount; ++i) {
            const char *line = va("%s\t%d\t%s\n", maps[i].name, maps[i].bots, maps[i].longname);
            FS_Write(line, strlen(line), out);
            Com_DPrintf("MAPLIST map=%s bots=%d name=%s\n", maps[i].name, maps[i].bots, maps[i].longname);
        }
        FS_FCloseFile(out);
    }
    Com_Printf("MAPLIST maps=%d bots=%d excluded=%d\n", mapCount, bots, excluded);
}

/* Split-screen views download into players/<N>/etmain: copy plain map packs (no native code)
 * into the shared etmain. Returns how many were copied; the caller restarts the file system. */
static int ConsolidateMaps(void) {
    WIN32_FIND_DATAA player, pack;
    HANDLE players, packs;
    char root[MAX_OSPATH], source[MAX_OSPATH], target[MAX_OSPATH], temporary[MAX_OSPATH + 8];
    int copied = 0;
    Q_strncpyz(root, Cvar_VariableString("fs_homepath"), sizeof(root));
    if ((players = FindFirstFileA(va("%s\\players\\*", root), &player)) == INVALID_HANDLE_VALUE) return 0;
    do {
        if (!(player.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) || player.cFileName[0] == '.') continue;
        if ((packs = FindFirstFileA(va("%s\\players\\%s\\etmain\\*.pk3", root, player.cFileName), &pack)) == INVALID_HANDLE_VALUE) continue;
        do {
            unzFile zip;
            qboolean map = qfalse, code = qfalse;
            Com_sprintf(source, sizeof(source), "%s\\players\\%s\\etmain\\%s", root, player.cFileName, pack.cFileName);
            Com_sprintf(target, sizeof(target), "%s\\etmain\\%s", root, pack.cFileName);
            if (GetFileAttributesA(target) != INVALID_FILE_ATTRIBUTES || !(zip = unzOpen(source))) continue;
            if (unzGoToFirstFile(zip) == UNZ_OK) do {
                char entry[MAX_QPATH];
                if (unzGetCurrentFileInfo(zip, NULL, entry, sizeof(entry), NULL, 0, NULL, 0) != UNZ_OK) continue;
                if (!Q_stricmpn(entry, "maps/", 5) && !strchr(entry + 5, '/') && Has(entry, ".bsp")) map = qtrue;
                {   /* Native code by extension (".so" must not match ".sounds"). */
                    const char *dot = strrchr(entry, '.');
                    if (dot && (!Q_stricmp(dot, ".dll") || !Q_stricmp(dot, ".so") || !Q_stricmp(dot, ".exe") || !Q_stricmp(dot, ".dylib"))) code = qtrue;
                }
            } while (unzGoToNextFile(zip) == UNZ_OK);
            unzClose(zip);
            if (!map || code) continue;
            Com_sprintf(temporary, sizeof(temporary), "%s.tmp", target);
            if (CopyFileA(source, temporary, FALSE) && MoveFileExA(temporary, target, 0)) {
                ++copied; Com_Printf("MAPLIST copied %s from player %s\n", pack.cFileName, player.cFileName);
            } else DeleteFileA(temporary);
        } while (FindNextFileA(packs, &pack));
        FindClose(packs);
    } while (FindNextFileA(players, &player));
    FindClose(players);
    return copied;
}

/* Startup and after online split-screen sessions: gather downloads, then list. */
void CL_RescanMaps(void) {
    if (CL_OnlinePane() || cls.state != CA_DISCONNECTED ||
        Q_stricmp(Cvar_VariableString("fs_game"), "et-rust")) return;
    if (ConsolidateMaps()) FS_Restart(0); /* As after a download: load the new packs. */
    CL_ScanMaps();
}

void CL_MapListInit(void) {
    Cmd_AddCommand("map_scan", CL_ScanMaps);
    Cmd_AddCommand("map_rescan", CL_RescanMaps);
    CL_RescanMaps();
}
